def get_closest_ver(versions: List[str], version: Optional[str], spec:
    SpecifierSet) ->Dict[str, Optional[Union[str, Version]]]:
    if not version or spec is None:
        return {'lower': None, 'upper': None}

    if not versions:
        return {'lower': None, 'upper': None}

    current = parse_version(version)

    # Filter out versions that match the spec (i.e., the current version)
    other_versions = [v for v in versions if not spec.contains(v, prereleases=True)]

